// Password vault for ATS candidate accounts (config/vault.json).
//   adapter none (default)  no account is ever created or used: unlocked() is false, findLogin()
//                           finds nothing, createLogin() and loginPassword() throw VaultDisabledError,
//                           and the apply runner hands the account portal to the user.
//   adapter op              the 1Password CLI. Account, vault and tag come from config (op.account,
//                           op.vault, op.tag); an empty account or vault lets op use its own default.
// A password is generated by op itself (--generate-password), so it is never on argv (visible to
// other processes and shell history) and never in the repo, data/, logs or screenshots. It is
// stored in the vault and read back BEFORE a sign-up form is sent. A locked or signed-out vault
// means no account is created. The apply runner also requires config/apply.json accounts.create.

import { spawn } from 'node:child_process';
import { randomInt } from 'node:crypto';
import { loadConfig } from '../config.mjs';

export const VAULT_TAG = 'jobba-hunt';

export class VaultDisabledError extends Error {
  constructor(message = 'no password vault is set up (config/vault.json adapter none): ATS accounts are handed to the user') {
    super(message);
    this.name = 'VaultDisabledError';
    this.vaultDisabled = true;
  }
}

// Common ATS password rules (Workday tenants): 8+ characters, an upper, a lower, a digit and a
// special character. The special set avoids quotes, backslashes and spaces.
export const PASSWORD_RULES = [/[A-Z]/, /[a-z]/, /[0-9]/, /[!@#$%^*\-_=+]/];
const SETS = ['ABCDEFGHJKLMNPQRSTUVWXYZ', 'abcdefghijkmnopqrstuvwxyz', '23456789', '!@#$%^*-_=+'];
// What a generated sign-up password must hold: an upper, a lower, a digit, a special, 12+ characters.
export const SIGNUP_RULES = [/[A-Z]/, /[a-z]/, /[0-9]/, /[^A-Za-z0-9]/, /^.{12,}$/];
const GENERATE = '--generate-password=letters,digits,symbols,24';
export function strongPassword(length = 24) {
  const all = SETS.join('');
  const chars = SETS.map((s) => s[randomInt(s.length)]);
  while (chars.length < length) chars.push(all[randomInt(all.length)]);
  for (let i = chars.length - 1; i > 0; i--) { const j = randomInt(i + 1); [chars[i], chars[j]] = [chars[j], chars[i]]; }
  return chars.join('');
}

// The real runner: op with optional stdin. 60 s per call (op may wait on the desktop app's unlock).
export const opRun = (bin = process.env.JOBBA_OP_BIN || 'op') => (args, { input = null } = {}) => new Promise((resolve) => {
  // No input means no stdin pipe: op reads a piped stdin as an item template.
  const p = spawn(bin, args, { stdio: [input == null ? 'ignore' : 'pipe', 'pipe', 'pipe'] });
  let stdout = '';
  let stderr = '';
  const timer = setTimeout(() => p.kill('SIGTERM'), 60000);
  p.stdout.on('data', (d) => { stdout += d; });
  p.stderr.on('data', (d) => { stderr += d; });
  p.on('error', (err) => { clearTimeout(timer); resolve({ code: 127, stdout, stderr: String(err.message) }); });
  p.on('close', (code) => { clearTimeout(timer); resolve({ code: code ?? 1, stdout, stderr }); });
  if (input != null) p.stdin.end(input);
});

// The op vault. `account` and `vault` are optional (op's defaults apply when empty); `tag` marks
// every item this project creates and limits every lookup to them.
export function makeVault(run, { account = '', vault = '', tag = VAULT_TAG } = {}) {
  const acct = account ? ['--account', account] : [];
  const inVault = vault ? ['--vault', vault] : [];
  const theTag = tag || VAULT_TAG;
  const json = (r) => { try { return JSON.parse(r.stdout); } catch { return null; } };
  return {
    kind: 'op',
    // Signed in and the vaults readable. Any failure (locked app, no session) is "locked".
    async unlocked() {
      const r = await run(['vault', 'list', '--format', 'json', ...acct]);
      return r.code === 0 && Array.isArray(json(r));
    },
    // The tagged item with exactly this title, or null.
    async findLogin(title) {
      const r = await run(['item', 'list', ...inVault, '--tags', theTag, '--format', 'json', ...acct]);
      if (r.code !== 0) throw new Error(`vault item list failed: ${String(r.stderr).trim().slice(0, 200)}`);
      return (json(r) || []).find((i) => i.title === title)?.id || null;
    },
    async loginPassword(itemId) {
      const r = await run(['item', 'get', itemId, '--fields', 'password', '--reveal', ...acct]);
      if (r.code !== 0) throw new Error('vault item get failed');
      return String(r.stdout).replace(/\r?\n$/, '');
    },
    // op generates the password itself (a stdin item template failed with "provide the item
    // category with '--category' flag"), so it never passes through stdin or argv. Read back and
    // checked for the sign-up character classes before any sign-up; a miss is regenerated in
    // place, twice.
    async createLogin({ title, url, username, notes = '' }) {
      if (!(await this.unlocked())) throw new Error('the vault is locked or signed out (op): the operator needs to unlock it');
      const r = await run(['item', 'create', '--category', 'Login', GENERATE, '--title', title, '--url', url,
        '--tags', theTag, ...inVault, '--format', 'json', ...acct,
        `username=${username}`, ...(notes ? [`notesPlain=${notes}`] : [])]);
      const id = r.code === 0 ? json(r)?.id : null;
      if (!id) throw new Error(`vault item create failed: ${String(r.stderr).trim().slice(0, 200)}`);
      for (let tries = 0; ; tries++) {
        const password = await this.loginPassword(id).catch(() => '');
        if (!password) throw new Error(`vault item ${id}: the password did not read back; no account was created`);
        if (SIGNUP_RULES.every((re) => re.test(password))) return { id, password };
        if (tries >= 2) throw new Error(`vault item ${id}: the generated password misses a character class; no account was created`);
        await run(['item', 'edit', id, GENERATE, ...acct]);
      }
    },
  };
}

// adapter none: nothing to unlock, nothing stored, nothing created.
export function noVault() {
  return {
    kind: 'none',
    async unlocked() { return false; },
    async findLogin() { return null; },
    async loginPassword() { throw new VaultDisabledError(); },
    async createLogin() { throw new VaultDisabledError(); },
  };
}

// The configured vault. `run` is injectable for tests; the default runs the op binary
// (JOBBA_OP_BIN, else config op.bin, else `op` on PATH).
export function openVault({ cfg = loadConfig('vault.json'), run = null } = {}) {
  const adapter = String(cfg?.adapter || 'none').toLowerCase();
  if (adapter === 'none') return noVault();
  if (adapter !== 'op') throw new Error(`config/vault.json: unknown vault adapter "${cfg.adapter}" (use op or none)`);
  const op = cfg.op || {};
  return makeVault(run || opRun(process.env.JOBBA_OP_BIN || op.bin || 'op'), { account: op.account || '', vault: op.vault || '', tag: op.tag || VAULT_TAG });
}
